35	@Component
36	public class OwnerAuditCreationAdvice {
37	
38	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
39	
40	    @Around("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
41	    public Object auditCreation(ProceedingJoinPoint joinPoint, Owner owner) throws Throwable {
42	        boolean created = owner.isNew();
43	        Object result = joinPoint.proceed();
44	        if (created) {
45	            String membershipNumber = owner.getCustomerCode() == null || owner.getRegistrationDate() == null ? null
46	                : owner.getCustomerCode() + "-M" + String.format("%02d", OwnerFiscalYear.yearOf(owner.getRegistrationDate()) % 100);
47	            AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
48	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
49	                OwnerMembershipLevel.of(owner), membershipNumber);
50	        }
51	        return result;
52	    }
53	}
