17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.lang.reflect.Method;
20	import java.lang.reflect.Type;
21	
22	import org.springframework.core.MethodParameter;
23	import org.springframework.core.Ordered;
24	import org.springframework.core.annotation.Order;
25	import org.springframework.http.HttpInputMessage;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.http.converter.HttpMessageConverter;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
31	import org.springframework.samples.petclinic.service.ClinicService;
32	import org.springframework.web.bind.annotation.ControllerAdvice;
33	import org.springframework.web.bind.annotation.ExceptionHandler;
34	import org.springframework.web.bind.annotation.ResponseBody;
35	import org.springframework.web.servlet.mvc.method.annotation.RequestBodyAdviceAdapter;
36	
37	/**
38	 * Rejects creating an owner whose derived {@code identityKey} exactly matches an existing
39	 * owner's, answering 409. The key is
40	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} and is the single
41	 * source of duplicate detection: telephone, email and household all contribute to it, so only
42	 * a whole-key match is a duplicate (household members with different telephones differ and are
43	 * both allowed). Kept as its own small advice so the rule stays a self-contained unit.
44	 */
45	@ControllerAdvice
46	@Order(Ordered.HIGHEST_PRECEDENCE)
47	public class OwnerUniqueIdentityAdvice extends RequestBodyAdviceAdapter {
48	
49	    private final ClinicService clinicService;
50	
51	    public OwnerUniqueIdentityAdvice(ClinicService clinicService) {
52	        this.clinicService = clinicService;
53	    }
54	
55	    @Override
56	    public boolean supports(MethodParameter methodParameter, Type targetType,
57	                            Class<? extends HttpMessageConverter<?>> converterType) {
58	        Method method = methodParameter.getMethod();
59	        return OwnerFieldsDto.class.equals(targetType)
60	            && method != null && "addOwner".equals(method.getName());
61	    }
62	
63	    @Override
64	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
65	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
66	        OwnerFieldsDto dto = (OwnerFieldsDto) body;
67	        String contact = OwnerIdentityKey.telephone(dto.getTelephone()) + '|' + OwnerIdentityKey.email(dto.getEmail());
68	        boolean duplicate = clinicService.findAllOwners().stream()
69	            .filter(o -> !Boolean.TRUE.equals(o.getDeleted()))
70	            .map(o -> OwnerIdentityKey.telephone(o.getTelephone()) + '|' + OwnerIdentityKey.email(o.getEmail()))
71	            .anyMatch(contact::equals);
72	        if (duplicate) {
73	            throw new DuplicateIdentityException();
74	        }
75	        return body;
76	    }
77	
78	    @ExceptionHandler(DuplicateIdentityException.class)
79	    @ResponseBody
80	    public ResponseEntity<String> handleDuplicateIdentity(DuplicateIdentityException e) {
